"""Minimum Insertion Steps to Make a String Palindrome.

Every character outside the longest palindromic subsequence needs a partner, so
the answer is n minus that subsequence's length.

Time: O(n^2)   Space: O(n)
"""


class Solution:
    def minInsertions(self, s: str) -> int:
        reverse = s[::-1]
        previous = [0] * (len(s) + 1)
        for a in s:
            current = [0]
            for j, b in enumerate(reverse):
                if a == b:
                    current.append(previous[j] + 1)
                else:
                    current.append(max(previous[j + 1], current[j]))
            previous = current
        return len(s) - previous[-1]
